// Tenant guard. "Prepare Reservation" is SHARED by every client: it must be told whose data this is (account id, or the
// calling workflow for the internal test chat) and whose calendar to use. No default: a guess is how a
// booking lands in the wrong hotel.
const inp = $input.first().json || {};
let d = inp;
if (typeof inp.query === 'string') { try { d = JSON.parse(inp.query); } catch (e) { d = inp; } }
else if (inp.query && typeof inp.query === 'object') { d = inp.query; }
const acct = String(d.accountId ?? '').trim(), wf = String(d.workflowId ?? '').trim();
if (!/^\d+$/.test(acct) && !wf) throw new Error('Prepare Reservation was called without accountId or workflowId - refusing to guess whose data to use.');
const bad = (v) => !v || typeof v !== 'string' || v.startsWith('__RECEPLY_');
if (bad(d.calendarId)) throw new Error('Prepare Reservation was called without this client calendarId (received ' + String(d.calendarId) + ') - refusing to guess whose calendar to use.');
return [{ json: Object.assign({}, d, { accountId: acct, workflowId: wf }) }];

// Bookings entered by hand exist only in the hotel calendar. An entry naming this room (Room / Dhoma / Soba
// <number>) during the stay blocks it. An entry during the stay that names NONE of the hotel's room numbers
// ("Family Suite - Anna", 2026-10-01) could be for any room: refuse to guess, hold nothing, hand over to a
// person. All-day entries count by date, so one starting on the check-out day does not. If the calendar
// cannot be read, fail safe: nothing stays held. Event titles never reach the AI.
const r = $('Prepare').first().json.r;
const evs = $input.all().map((i) => i.json || {});
if (evs.find((e) => e.error)) return [{ json: { free: false, reason: 'calendar check failed', message: 'The hotel calendar could not be checked right now, so nothing is held. Apologize and offer to connect the guest with a person, or try again in a moment.' } }];
const esc = (s) => String(s).replace(/[.*+?^$(){}|[\]\\]/g, '\\$&');
const re = new RegExp('\\b(room|dhoma|soba)\\s*' + esc(r.room) + '\\b', 'i');
const rooms = (r.all_rooms || []).map(String);
const namesARoom = (t) => rooms.some((n) => new RegExp('(^|[^0-9A-Za-z])' + esc(n) + '([^0-9A-Za-z]|$)').test(t));
const overlaps = (e) => (e.start && e.start.date && !e.start.dateTime) ? (e.start.date < String(r.check_out) && String((e.end && e.end.date) || e.start.date) > String(r.check_in)) : true;
const live = evs.filter((e) => e.id && e.status !== 'cancelled' && overlaps(e));
const clash = live.find((e) => re.test(String(e.summary || '')));
if (clash) return [{ json: { free: false, reason: 'calendar entry for the room', message: 'Room ' + r.room + ' already has an entry in the hotel calendar for part of those dates, so nothing is held. Check another suitable room with "Check Availability" and prepare again.' } }];
const unclear = rooms.length ? live.find((e) => !namesARoom(String(e.summary || ''))) : null;
if (unclear) return [{ json: { free: false, reason: 'calendar entry without a room number', message: 'The hotel calendar has an entry during these dates that does not say which room it is for, so no room can be confirmed free for these dates and nothing is held. Do not offer other rooms for these dates. Apologize, call "Escalate To Human" with the reason "calendar entry without a room number, ' + r.check_in + ' to ' + r.check_out + '", and tell the guest a team member will confirm availability.' } }];
return [{ json: { free: true } }];
